package Image::ExifTool::PrintIM;use strict;use vars qw($VERSION);use Image::ExifTool qw(:DataAccess);$VERSION='1.07';sub ProcessPrintIM($$$);%Image::ExifTool::PrintIM::Main=(PROCESS_PROC=>\&ProcessPrintIM,GROUPS=>{0=>'PrintIM',1=>'PrintIM',2=>'Printing' },PRINT_CONV=>'sprintf("0x%.8x", $val)',TAG_PREFIX=>'PrintIM',PrintIMVersion=>{Description=>'PrintIM Version',PrintConv=>undef,},);sub ProcessPrintIM($$$) {my ($et,$dirInfo,$tagTablePtr)=@_;my$dataPt=$$dirInfo{DataPt};my$offset=$$dirInfo{DirStart};my$size=$$dirInfo{DirLen};my$verbose=$et->Options('Verbose');unless ($size){$et->Warn('Empty PrintIM data',1);return 0}unless ($size > 15){$et->Warn('Bad PrintIM data');return 0}unless (substr($$dataPt,$offset,7)eq 'PrintIM'){$et->Warn('Invalid PrintIM header');return 0}my$num=Get16u($dataPt,$offset + 14);if ($size < 16 + $num * 6){ToggleByteOrder();$num=Get16u($dataPt,$offset + 14);if ($size < 16 + $num * 6){$et->Warn('Bad PrintIM size');return 0}}$verbose and $et->VerboseDir('PrintIM',$num);$et->HandleTag($tagTablePtr,'PrintIMVersion',substr($$dataPt,$offset + 8,4),DataPt=>$dataPt,Start=>$offset + 8,Size=>4,);my$n;for ($n=0;$n<$num;++$n){my$pos=$offset + 16 + $n * 6;my$tag=Get16u($dataPt,$pos);my$val=Get32u($dataPt,$pos + 2);$et->HandleTag($tagTablePtr,$tag,$val,Index=>$n,DataPt=>$dataPt,Start=>$pos + 2,Size=>4,)}return 1}1;